import { revalidateTag } from 'next/cache';
import { getAllProducts } from '../lib/db';

// Cached child component that fetches product data
async function ProductList() {
  'use cache';
  const cacheTag = 'products';

  const products = await getAllProducts();

  return (
    <div className="product-list">
      <h2>Products (Cached)</h2>
      <p className="cache-info">
        Cache Tag: <code>{cacheTag}</code> | Last fetched: {new Date().toLocaleTimeString()}
      </p>
      <ul style={{ listStyle: 'none', padding: 0 }}>
        {products.map((product) => (
          <li key={product.id} style={{
            padding: '10px',
            margin: '10px 0',
            border: '1px solid #ddd',
            borderRadius: '4px'
          }}>
            <strong>{product.name}</strong> - ${product.price}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function Page() {
  // Server action for cache invalidation
  async function invalidateProductCache() {
    'use server';
    revalidateTag('products');
  }

  return (
    <div style={{ padding: '20px', fontFamily: 'system-ui, sans-serif' }}>
      <h1>Product Listing with Cache Invalidation</h1>

      <div style={{ marginBottom: '20px' }}>
        <p>
          This demo shows efficient data caching with selective invalidation:
        </p>
        <ul>
          <li>Product data is cached using the <code>'use cache'</code> directive</li>
          <li>Tagged with <code>"products"</code> for selective invalidation</li>
          <li>Form below invalidates only the products cache when submitted</li>
        </ul>
      </div>

      <ProductList />

      <form action={invalidateProductCache} style={{ marginTop: '20px' }}>
        <button
          type="submit"
          style={{
            padding: '10px 20px',
            fontSize: '16px',
            backgroundColor: '#0070f3',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          Invalidate Products Cache
        </button>
        <p style={{ fontSize: '14px', color: '#666', marginTop: '10px' }}>
          Click to force refetch product data. The timestamp will update to show fresh data.
        </p>
      </form>

      <div style={{
        marginTop: '30px',
        padding: '15px',
        backgroundColor: '#f5f5f5',
        borderRadius: '4px'
      }}>
        <h3>How it works:</h3>
        <ol>
          <li><strong>Caching:</strong> ProductList uses <code>'use cache'</code> to cache results</li>
          <li><strong>Tagging:</strong> Cache is tagged with "products" for targeted invalidation</li>
          <li><strong>Invalidation:</strong> Server action calls <code>revalidateTag('products')</code></li>
          <li><strong>Revalidation:</strong> Next request fetches fresh data and re-caches it</li>
        </ol>
      </div>
    </div>
  );
}

